def simulate_growth(n, s):
    """
    Simulates the process until saturation (G = n^2) for small n,
    assuming optimal selection maximizes immediate gain, which simplifies
    to min(s, n^2 - G) since the n x n grid is small compared to the 75x75 area.
    Returns the final total number of green cells G.
    """
    n_sq = n * n
    G = 1

    if n_sq == 1:
        return 1

    # Simple progression until saturation
    while G < n_sq:
        gain = min(s, n_sq - G)
        G += gain

    return G

results = {}
for s in [1, 2, 3, 4]:
    results[s] = {}
    for n in range(1, 6): # n=1 to 5
        G = simulate_growth(n, s)
        ratio = G / n
        results[s][n] = {"G": G, "Ratio (G/n)": ratio}

print("--- Simulation Results (G / n ratio) ---")
for s in results:
    print(f"s = {s}:")
    for n in range(1, 6):
        data = results[s][n]
        print(f"  n = {n}: G = {data['G']}, Ratio = {data['Ratio (G/n)']:.4f}")

